{"command":"cat <<'EOF' > src/parser.rs
#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Word(String),
    Pipe,
    RedirectOut,
    RedirectAppend,
    RedirectIn,
    RedirectErr,
    Semi,
    And,
    Or,
    LParen,
    RParen,
}

pub struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    pub fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    pub fn parse(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        while let Some(token) = self.next_token() {
            tokens.push(token);
        }
        tokens
    }

    fn next_token(&mut self) -> Option<Token> {
        self.skip_whitespace();
        if self.pos >= self.input.len() {
            return None;
        }

        let remaining = &self.input[self.pos..];
        if remaining.starts_with("&&") {
            self.pos += 2;
            return Some(Token::And);
        }
        if remaining.starts_with("||") {
            self.pos += 2;
            return Some(Token::Or);
        }
        if remaining.starts_with(">>") {
            self.pos += 2;
            return Some(Token::RedirectAppend);
        }
        if remaining.starts_with("2>") {
            self.pos += 2;
            return Some(Token::RedirectErr);
        }
        if remaining.starts_with('|') {
            self.pos += 1;
            return Some(Token::Pipe);
        }
        if remaining.starts_with('>') {
            self.pos += 1;
            return Some(Token::RedirectOut);
        }
        if remaining.starts_with('<') {
            self.pos += 1;
            return Some(Token::RedirectIn);
        }
        if remaining.starts_with(';') {
            self.pos += 1;
            return Some(Token::Semi);
        }
        if remaining.starts_with('(') {
            self.pos += 1;
            return Some(Token::LParen);
        }
        if remaining.starts_with(')') {
            self.pos += 1;
            return Some(Token::RParen);
        }

        let mut word = String::new();
        let mut in_single_quote = false;
        let mut in_double_quote = false;
        let mut escaped = false;

        while self.pos < self.input.len() {
            let c = self.input.as_bytes()[self.pos] as char;
            if escaped {
                word.push(c);
                escaped = false;
                self.pos += 1;
            } else if c == '\\' {
                if in_single_quote {
                    word.push(c);
                } else {
                    escaped = true;
                }
                self.pos += 1;
            } else if c == '\'' {
                if in_double_quote {
                    word.push(c);
                } else {
                    in_single_quote = !in_single_quote;
                }
                self.pos += 1;
            } else if c == '"' {
                if in_single_quote {
                    word.push(c);
                } else {
                    in_double_quote = !in_double_quote;
                }
                self.pos += 1;
            } else if !in_single_quote && !in_double_quote && " \t\n|&;><()".contains(c) {
                break;
            } else {
                word.push(c);
                self.pos += 1;
            }
        }

        if !word.is_empty() {
            Some(Token::Word(word))
        } else {
            None
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() {
            let c = self.input.as_bytes()[self.pos] as char;
            if c.is_whitespace() {
                self.pos += 1;
            } else {
                break;
            }
        }
    }
}
EOF
"}

