pub struct Shell {
    pub vars: HashMap<String, String>,
    pub aliases: HashMap<String, String>,
}

impl Shell {
    pub fn new() -> Self {
        let mut vars = HashMap::new();
        for (k, v) in env::vars() {
            vars.insert(k, v);
        }
        Self {
            vars,
            aliases: HashMap::new(),
        }
    }

    pub fn execute_line(&mut self, line: &str) -> i32 {
        let mut parser = Parser::new(line);
        let tokens = parser.parse();
        if tokens.is_empty() {
            return 0;
        }

        self.execute_tokens(tokens)
    }

    pub fn execute_tokens(&mut self, tokens: Vec<Token>) -> i32 {
        // This is a very simplified execution engine.
        // It should handle ;, &&, ||, pipes, and redirections.

        // For now, let's just handle a single command with potential pipes.
        let mut commands = Vec::new();
        let mut current_cmd = Vec::new();

        for token in tokens {
            match token {
                Token::Pipe => {
                    commands.push(current_cmd);
                    current_cmd = Vec::new();
                }
                Token::Semi => {
                    // Execute current sequence and start new
                    // Not implemented correctly for pipes yet
                }
                _ => {
                    current_cmd.push(token);
                }
            }
        }
        commands.push(current_cmd);

        self.execute_pipeline(commands)
    }

    fn execute_pipeline(&mut self, commands: Vec<Vec<Token>>) -> i32 {
        let mut last_stdout = Stdio::inherit();
        let mut children = Vec::new();

        for (i, cmd_tokens) in commands.iter().enumerate() {
            let is_last = i == commands.len() - 1;

            let mut args = Vec::new();
            let mut stdout = if is_last { Stdio::inherit() } else { Stdio::piped() };
            let mut stderr = Stdio::inherit();
            let mut stdin = last_stdout;

            // Simple word expansion and redirection handling
            let mut i = 0;
            while i < cmd_tokens.len() {
                match &cmd_tokens[i] {
                    Token::Word(w) => {
                        let expanded = self.expand_vars(w);
                        // Word splitting
                        for part in expanded.split_whitespace() {
                            args.push(part.to_string());
                        }
                    }
                    Token::RedirectOut => {
                        i += 1;
                        if let Some(Token::Word(file)) = cmd_tokens.get(i) {
                            let f = File::create(file).expect("failed to open file");
                            stdout = Stdio::from(f);
                        }
                    }
                    Token::RedirectAppend => {
                        i += 1;
                        if let Some(Token::Word(file)) = cmd_tokens.get(i) {
                            let f = std::fs::OpenOptions::new().append(true).create(true).open(file).expect("failed to open file");
                            stdout = Stdio::from(f);
                        }
                    }
                    Token::RedirectErr => {
                        i += 1;
                        if let Some(Token::Word(file)) = cmd_tokens.get(i) {
                            let f = File::create(file).expect("failed to open file");
                            stderr = Stdio::from(f);
                        }
                    }
                    _ => {}
                }
                i += 1;
            }

            if args.is_empty() { continue; }

            // Handle builtins
            if args[0] == "cd" {
                let dir = args.get(1).map(|s| s.as_str()).unwrap_or("/");
                if let Err(e) = env::set_current_dir(dir) {
                    eprintln!("cd: {}", e);
                    return 1;
                }
                continue;
            }
            if args[0] == "export" {
                if let Some(arg) = args.get(1) {
                    if let Some((k, v)) = arg.split_once('=') {
                        self.vars.insert(k.to_string(), v.to_string());
                        env::set_var(k, v);
                    }
                }
                continue;
            }
            if args[0] == "exit" {
                let code = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(0);
                std::process::exit(code);
            }

            let mut child = Command::new(&args[0])
                .args(&args[1..])
                .stdin(stdin)
                .stdout(stdout)
                .stderr(stderr)
                .spawn();

            match child {
                Ok(mut c) => {
                    if !is_last {
                        last_stdout = Stdio::from(c.stdout.take().unwrap());
                    }
                    children.push(c);
                }
                Err(e) => {
                    eprintln!("nsh: command not found `{}`", args[0]);
                    return 127;
                }
            }
        }

        let mut last_status = 0;
        for mut child in children {
            last_status = child.wait().unwrap().code().unwrap_or(0);
        }
        last_status
    }

    fn expand_vars(&self, word: &str) -> String {
        let mut result = String::new();
        let mut i = 0;
        let bytes = word.as_bytes();
        while i < bytes.len() {
            if bytes[i] == b'$' {
                i += 1;
                let mut name = String::new();
                while i < bytes.len() && (bytes[i] as char).is_alphanumeric() {
                    name.push(bytes[i] as char);
                    i += 1;
                }
                if let Some(val) = self.vars.get(&name) {
                    result.push_str(val);
                }
            } else {
                result.push(bytes[i] as char);
                i += 1;
            }
        }
        result
    }
}
