use std::env;
use std::process::Command;

pub fn eval_prompt(prompt: &str) -> String {
    let mut result = String::new();
    let mut i = 0;
    let bytes = prompt.as_bytes();

    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 1;
            if i >= bytes.len() { break; }
            if bytes[i] == b'i' && prompt[i..].starts_with("if{") {
                // Handle \if{cond}{then}{else}
                // Simplified for now
                i += 2; // skip "if"
                // ... parsing of if expression ...
            } else {
                let mut name = String::new();
                if bytes[i] == b'{' {
                    i += 1;
                    while i < bytes.len() && bytes[i] != b'}' {
                        name.push(bytes[i] as char);
                        i += 1;
                    }
                    if i < bytes.len() { i += 1; } // skip '}'
                }

                match name.as_str() {
                    "username" => {
                        result.push_str(&env::var("USER").unwrap_or_default());
                    }
                    "hostname" => {
                        let host = Command::new("hostname").output().ok()
                            .and_then(|o| String::from_utf8(o.stdout).ok())
                            .unwrap_or_default();
                        result.push_str(host.trim());
                    }
                    "current_dir" => {
                        let cur_dir = env::current_dir().unwrap_or_default();
                        let cur_dir_str = cur_dir.to_str().unwrap_or_default();
                        let home = env::var("HOME").unwrap_or_default();
                        if !home.is_empty() && cur_dir_str.starts_with(&home) {
                            result.push('~');
                            result.push_str(&cur_dir_str[home.len()..]);
                        } else {
                            result.push_str(cur_dir_str);
                        }
                    }
                    "reset" => result.push_str("\x1b[0m"),
                    "bold" => result.push_str("\x1b[1m"),
                    "red" => result.push_str("\x1b[31m"),
                    "green" => result.push_str("\x1b[32m"),
                    "yellow" => result.push_str("\x1b[33m"),
                    "blue" => result.push_str("\x1b[34m"),
                    "magenta" => result.push_str("\x1b[35m"),
                    "cyan" => result.push_str("\x1b[36m"),
                    _ => {
                        result.push('\\');
                        result.push('{');
                        result.push_str(&name);
                        result.push('}');
                    }
                }
                continue;
            }
        } else {
            result.push(bytes[i] as char);
        }
        i += 1;
    }
    result
}
