                    i += 1;
                }
            }
            "-l" | "--login" => {
                is_login = true;
            }
            "--norc" => {
                use_rc = false;
            }
            _ => {
                // If it's a file to run
                if command_to_run.is_none() {
                    // Run script file
                }
            }
        }
        i += 1;
    }

    if let Some(cmd) = command_to_run {
        let status = shell.execute_line(&cmd);
        std::process::exit(status);
    }

    // Interactive mode
    if io::stdin().is_terminal() {
        // Normal interactive mode
    } else {
        eprintln!("nsh: warning: stdout is not a tty");
    }

    loop {
        let default_prompt = "\\{current_dir} $ ";
        let prompt_str = env::var("PROMPT").unwrap_or_else(|_| default_prompt.to_string());
        print!("{}", eval_prompt(&prompt_str));
        io::stdout().flush().unwrap();

        let mut input = String::new();
        match io::stdin().read_line(&mut input) {
