        let mut last_status = 0;
        let mut current_pos = 0;

        while current_pos < tokens.len() {
            let mut pipeline = Vec::new();
            let mut sep = None;

            while current_pos < tokens.len() {
                let token = &tokens[current_pos];
                match token {
                    Token::Semi | Token::And | Token::Or => {
                        sep = Some(token.clone());
                        current_pos += 1;
                        break;
                    }
                    _ => {
                        pipeline.push(token.clone());
                        current_pos += 1;
                    }
                }
            }

            if pipeline.is_empty() {
                continue;
            }

            let mut commands = Vec::new();
            let mut current_cmd = Vec::new();
            for t in pipeline {
                if t == Token::Pipe {
                    commands.push(current_cmd);
                    current_cmd = Vec::new();
                } else {
                    current_cmd.push(t);
                }
            }
            commands.push(current_cmd);

            last_status = self.execute_pipeline(commands);

            if let Some(s) = sep {
                match s {
                    Token::And => {
                        if last_status != 0 {
                            while current_pos < tokens.len() {
                                if matches!(tokens[current_pos], Token::Semi | Token::Or) {
                                    break;
                                }
                                current_pos += 1;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
        last_status
    }

