        let mut prev_child: Option<std::process::Child> = None;
        let mut last_status = 0;

        for (i, cmd_tokens) in commands.iter().enumerate() {
            let is_last = i == commands.len() - 1;

            let mut args = Vec::new();
            let mut current_stdout = if is_last { Stdio::inherit() } else { Stdio::piped() };
            let mut current_stderr = Stdio::inherit();
            let mut current_stdin = if let Some(mut prev) = prev_child.take() {
                Stdio::from(prev.stdout.take().expect("Failed to get stdout from previous command"))
            } else {
                Stdio::inherit()
            };

