                        j += 1;
                        if let Some(Token::Word(file)) = cmd_tokens.get(j) {
                            let f = std::fs::OpenOptions::new().append(true).create(true).open(file).expect("failed to open file");
                            current_stdout = Stdio::from(f);
                        }
                    }
