                .args(&args[1..])
                .stdin(current_stdin)
                .stdout(current_stdout)
                .stderr(current_stderr)
                .spawn();

            match child {
                Ok(c) => {
                    if is_last {
                        let mut final_child = c;
                        last_status = final_child.wait().unwrap().code().unwrap_or(0);
                    } else {
                        prev_child = Some(c);
                    }
                }
                Err(_) => {
                    eprintln!("nsh: command not found `{}`", args[0]);
                    last_status = 127;
                }
            }
        }

        last_status
    }

    fn expand_vars(&self, word: &str) -> String {
        let mut result = String::new();
        let mut i = 0;
        let bytes = word.as_bytes();
        while i < bytes.len() {
            if bytes[i] == b'$' {
                i += 1;
                let mut name = String::new();
                while i < bytes.len() && (bytes[i] as char).is_alphanumeric() {
                    name.push(bytes[i] as char);
                    i += 1;
                }
                if let Some(val) = self.vars.get(&name) {
                    result.push_str(val);
                } else if let Ok(val) = env::var(&name) {
                    result.push_str(&val);
                }
            } else {
                result.push(bytes[i] as char);
                i += 1;
            }
        }
        result
    }
}
