                "alias" => {
                    if args.len() == 1 {
                        for (k, v) in &self.aliases {
                            println!("alias {}='{}'", k, v);
                        }
                    } else if let Some(arg) = args.get(1) {
                        if let Some((k, v)) = arg.split_once('=') {
                            self.aliases.insert(k.to_string(), v.to_string());
                        }
                    }
                    last_status = 0;
                    continue;
                }
                "unalias" => {
                    if let Some(k) = args.get(1) {
                        self.aliases.remove(k);
                    }
                    last_status = 0;
                    continue;
                }
                "exit" => {
                    let code = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(0);
                    std::process::exit(code);
                }
                _ => {}
            }

            let cmd_name = if let Some(expanded) = self.aliases.get(&args[0]) {
                expanded.clone()
            } else {
                args[0].clone()
            };

            let mut final_args: Vec<String> = cmd_name.split_whitespace().map(|s| s.to_string()).collect();
            final_args.extend(args[1..].iter().cloned());

            let child = Command::new(&final_args[0])
                .args(&final_args[1..])
                .stdin(current_stdin)
                .stdout(current_stdout)
                .stderr(current_stderr)
                .spawn();

            match child {
                Ok(c) => {
                    if is_last {
                        let mut final_child = c;
                        last_status = final_child.wait().unwrap().code().unwrap_or(0);
                    } else {
                        prev_child = Some(c);
                    }
                }
                Err(_) => {
                    eprintln!("nsh: command not found `{}`", final_args[0]);
                    last_status = 127;
                }
            }
        }

        last_status
    }

    fn expand_vars(&self, word: &str) -> String {
        let mut result = String::new();
        let mut i = 0;
        let bytes = word.as_bytes();
        while i < bytes.len() {
            if bytes[i] == b'$' {
                i += 1;
                let mut name = String::new();
                if i < bytes.len() && bytes[i] == b'?' {
                    result.push_str(&self.last_status.to_string());
                    i += 1;
                } else {
                    while i < bytes.len() && (bytes[i] as char).is_alphanumeric() {
                        name.push(bytes[i] as char);
                        i += 1;
                    }
                    if let Some(val) = self.vars.get(&name) {
                        result.push_str(val);
                    } else if let Ok(val) = env::var(&name) {
                        result.push_str(&val);
                    }
                }
            } else {
                result.push(bytes[i] as char);
                i += 1;
            }
        }
        result
    }
}
